INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Müssen Unternehmen laut DSGVO immer eine Einwilligung einholen?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Rechtsgrundlagen möglich"}, {"text": "Ja", "correct": false, "because": "Einwilligung ist nur eine Option"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht haben Betroffene laut DSGVO?', 3, '[{"text": "Auskunft", "correct": true, "because": "Betroffene können Daten einsehen"}, {"text": "Maximale Speicherung", "correct": false, "because": "Kein Betroffenenrecht"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Kein DSGVO-Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt die DSGVO an Unternehmen?', 5, '[{"text": "Datenlöschung ermöglichen", "correct": true, "because": "Recht auf Vergessenwerden"}, {"text": "Transparenz sicherstellen", "correct": true, "because": "Informationspflicht"}, {"text": "Unbegrenzte Datensammlung", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nicht datenschutzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Betroffene haben ein Recht auf Datenportabilität. b) Unternehmen müssen alle Daten speichern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicherung widerspricht DSGVO"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Umsetzung von DSGVO-Anforderungen?', 4, '[{"text": "Rechte der Betroffenen", "correct": false, "because": "Kern der DSGVO"}, {"text": "Dokumentationspflicht", "correct": false, "because": "Nachweis erforderlich"}, {"text": "Visuelle Gestaltung", "correct": true, "because": "Nicht datenschutzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Recht auf Löschung Ausnahmen hat?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. gesetzliche Aufbewahrung"}, {"text": "Nein", "correct": false, "because": "Ausnahmen sind vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflicht haben Unternehmen bei einer Datenpanne?', 3, '[{"text": "Meldung an Aufsichtsbehörde", "correct": true, "because": "Innerhalb 72 Stunden"}, {"text": "Daten sofort löschen", "correct": false, "because": "Nicht primäre Pflicht"}, {"text": "Nichts tun", "correct": false, "because": "Meldepflicht besteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte der Betroffenen sind in der DSGVO enthalten?', 5, '[{"text": "Berichtigung", "correct": true, "because": "Korrigieren falscher Daten"}, {"text": "Einschränkung der Verarbeitung", "correct": true, "because": "Begrenzt Nutzung"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenweitergabe", "correct": false, "because": "Kein Betroffenenrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DSGVO schützt nur EU-Bürger. b) Unternehmen müssen Auskunft geben. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "DSGVO gilt für alle Daten in der EU"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Einhaltung der DSGVO?', 4, '[{"text": "Datenschutzbeauftragter", "correct": false, "because": "Bei Bedarf Pflicht"}, {"text": "Verzeichnis der Verarbeitungstätigkeiten", "correct": false, "because": "Nachweispflicht"}, {"text": "Maximale Datensammlung", "correct": true, "because": "Widerspricht Minimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt die DSGVO auch außerhalb der EU?', 2, '[{"text": "Ja", "correct": true, "because": "Für Daten von EU-Bürgern"}, {"text": "Nein", "correct": false, "because": "Extraterritoriale Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen das Recht auf Auskunft?', 4, '[{"text": "Datenübersicht bereitstellen", "correct": true, "because": "Erfüllt Auskunftspflicht"}, {"text": "Klare Kommunikation", "correct": true, "because": "Fördert Transparenz"}, {"text": "Daten verschweigen", "correct": false, "because": "Verletzt das Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die DSGVO nur für große Firmen gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Datenverarbeiter"}, {"text": "Ja", "correct": false, "because": "Unabhängig von Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer DSGVO-konformen Datenverarbeitung?', 3, '[{"text": "Rechte der Betroffenen", "correct": true, "because": "Kern der DSGVO"}, {"text": "Schnelle Datenweitergabe", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenportabilität ist ein Betroffenenrecht. b) Unternehmen dürfen Daten unbegrenzt speichern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicherbegrenzung gilt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen laut DSGVO?', 5, '[{"text": "Datenpannen melden", "correct": true, "because": "Schutz der Betroffenen"}, {"text": "Auskunft erteilen", "correct": true, "because": "Recht der Nutzer"}, {"text": "Alle Daten speichern", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Daten verkaufen", "correct": false, "because": "Verletzt Zweckbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Umsetzung des Rechts auf Löschung unwichtig?', 3, '[{"text": "Fristen einhalten", "correct": false, "because": "Pflicht bei Anfrage"}, {"text": "Rechtsgrundlage prüfen", "correct": false, "because": "Ausnahmen beachten"}, {"text": "Farbschema der Website", "correct": true, "because": "Nicht datenschutzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der DSGVO? Gilt sie nur für personenbezogene Daten?', 3, '[{"text": "Ja", "correct": true, "because": "Fokus auf Privatsphäre"}, {"text": "Nein", "correct": false, "because": "Nur personenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unternehmen Strafen bei DSGVO-Verstößen riskieren?', 2, '[{"text": "Ja", "correct": true, "because": "Bis zu 20 Mio. Euro möglich"}, {"text": "Nein", "correct": false, "because": "Sanktionen vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme hilft bei der Datenportabilität?', 4, '[{"text": "Daten in lesbarem Format bereitstellen", "correct": true, "because": "Erfüllt das Recht"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Schutz, nicht Portabilität"}, {"text": "Daten verbergen", "correct": false, "because": "Verletzt das Recht"}]');
